
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_hcth_120_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_hcth_120", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.529806527934090e+00, -4.438061954133865e+00, -4.309623367395266e+00, -4.131964885206156e+00, -3.890476963528851e+00, -3.570480428980275e+00, -3.162101795891229e+00, -2.669875576204930e+00, -2.128395264921957e+00, -1.609364011798961e+00, -1.120051096317012e+00, -7.746191134439500e-01, -6.655061916481195e-01, -5.432739298977999e-01, -3.917654938953249e-01, -2.513673462593665e-01, -1.524880602400386e-01, -6.603601668919865e-02, -1.647402124704987e-02, -2.025538512534823e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


